from pyspark.sql import functions as F


def solve(employees_raw):
    path = "/tmp/hr/export"
    employees_raw.write.mode("overwrite").text(path)
    people = spark.read.csv(path, sep=";", inferSchema=True)
    return people.select(
        F.col("_c0").alias("employee_id"),
        F.col("_c4").alias("salary"),
        F.col("_c5").alias("hire_date"),
    )
